static const char SLR_GEN_HLSL_PHONG_FLAT[] = "#define SL_FLAT 1\n""\n""//============================================================================\n""// SlShadersCommon.hlsli —— SLangRender 固化 shader 共享核心\n""//\n""// 提炼自 RenderTest/shader/*.shader（Unity URP）的 HLSL 光照库\n""//（SLangLighting.hlsl），并适配 cvm_render_lib 管线的场景常量约定：\n""//   - PerDraw / LightBlock 两个 std140 cbuffer，成员名与布局和\n""//     RHI 内建着色器（VS_PSCENE / FS_PFLAT / FS_PHONG_*）逐字一致；\n""//   - 2D 伪 3D 光照约定（v3.3/v3.4，GL/GLES/D3D11 三方公式一致）：\n""//     N = normalize(float3(vNrm, 0.75))，V = (0,0,1)，\n""//     直射 L = normalize(float3(uDirDir.xy, 0.6))，\n""//     聚光 L 沿 -toF + 0.6 高度分量（锥角平滑 + 距离平方衰减）。\n""//\n""// 本文件由 build-shaders.ps1 在编译前拼接到每个效果 .hlsl 头部\n""//（glslang 不处理 #include），拼接产物即「d3d11 源码」形态的固化源。\n""//============================================================================\n""\n""// ---- 场景常量（std140；column_major 显式声明，抵消 glslang HLSL 默认\n""//      row_major 的差异——与 GL 内建着色器默认列主序字节级一致）----\n""cbuffer PerDraw : register(b0)\n""{\n""    column_major float4x4 uMVP[64];\n""    float4 uColor[64];\n""    float4 uWMat[128];\n""    float4 uSpec[64];\n""};\n""cbuffer LightBlock : register(b4)\n""{\n""    float4 uAmbient;\n""    float4 uDirColor;\n""    float4 uDirDir;\n""    float4 uSpotColor;\n""    float4 uSpotPosRange;\n""    float4 uSpotDirCos;\n""    // N2a/N2b shadow map（尾部追加，旧布局不变）：级联 0 光空间 VP\n""    // （column_major mat4，与 uMVP 同构）+ 参数（enable/bias/strength/\n""    // texel）+ 深度/行适配（zxform：D3D11 直通 + 行镜像；GL/GLES\n""    // *2-1 + 恒等）+ N2b CSM 级联段（v 分割表 / 级联数 / 级联 1..3 VP）\n""    column_major float4x4 uLightVP;\n""    float4 uShadowParam;\n""    float4 uShadowZx;\n""    float4 uShadowSplit;    // N2b：4 级联 v 左端边界（split[i+1]=右端）\n""    float4 uShadowInfo;     // N2b：x = 级联数（1/4），y = 末级右端 v\n""    column_major float4x4 uLightVP1;  // N2b：级联 1 VP\n""    column_major float4x4 uLightVP2;  // N2b：级联 2 VP\n""    column_major float4x4 uLightVP3;  // N2b：级联 3 VP\n""};\n""\n""// N2a：shadow 深度纹理（D3D11 t1；GL/GLES cross 后按名绑 TEXTURE2）。\n""// POINT + CLAMP 采样（2D 深度剖面本质 1D，PCF 在 shader 手动做）\n""Texture2D uShadowTex : register(t1);\n""SamplerState uShadowSamp : register(s1);\n""\n""// ---- 松散 uniform（按名查找）：glslang 将其收进 _Global 隐式块，\n""//      固化脚本把 _Global 溶解回松散形态（GL/GLES 按名\n""//      glGetUniformLocation(\"uObjIndex\")，与内建着色器一致）----\n""cbuffer PerObj : register(b1) { int uObjIndex; float3 _pad; };\n""\n""// ---- 场景顶点 -> 片元 传递结构（与内建 VS_PSCENE 的 vUv/vWorld/vNrm/vObj\n""//      按名链接；固化脚本经 spirv-cross --rename-interface-variable 统一\n""//      命名为 vUv/vWorld/vNrm/vObj，可与内建 vert 混搭链接）----\n""struct PSceneV2P\n""{\n""    float2 uv    : TEXCOORD0;\n""    float2 world : TEXCOORD1;\n""    float2 nrm   : TEXCOORD2;\n""    nointerpolation int obj : TEXCOORD3;   // 实例槽号（flat，逐片元恒定）\n""};\n""\n""//============================================================================\n""// 光照函数库（提炼自 SLangLighting.hlsl，零 Unity 依赖）\n""//============================================================================\n""\n""//--- 漫反射 ---------------------------------------------------------------\n""\n""float3 DiffuseLambert(float3 albedo, float3 lightColor, float NdotL)\n""{\n""    return albedo * lightColor * saturate(NdotL);\n""}\n""\n""// Half-Lambert（包裹式漫反射，暗部不死黑）\n""float3 DiffuseHalfLambert(float3 albedo, float3 lightColor, float NdotL)\n""{\n""    float wrap = NdotL * 0.5 + 0.5;\n""    return albedo * lightColor * (wrap * wrap);\n""}\n""\n""//--- 高光 -----------------------------------------------------------------\n""\n""// 经典 Phong：R = reflect(-L, N)，R 与 V 越接近高光越强\n""float3 SpecularPhong(float3 lightColor, float3 N, float3 L, float3 V,\n""                     float shininess, float intensity)\n""{\n""    float3 R = reflect(-L, N);\n""    float spec = pow(saturate(dot(R, V)), max(shininess, 1.0));\n""    return lightColor * spec * intensity;\n""}\n""\n""// Blinn-Phong（半 Phong）：H = normalize(L + V)，dot(N, H) 代替 dot(R, V)\n""float3 SpecularBlinnPhong(float3 lightColor, float3 N, float3 L, float3 V,\n""                          float shininess, float intensity)\n""{\n""    float3 H = normalize(L + V);\n""    float spec = pow(saturate(dot(N, H)), max(shininess, 1.0));\n""    return lightColor * spec * intensity;\n""}\n""\n""//--- 边缘 / 菲涅尔 ---------------------------------------------------------\n""\n""float FresnelSchlick(float cosTheta, float f0)\n""{\n""    return f0 + (1.0 - f0) * pow(1.0 - saturate(cosTheta), 5.0);\n""}\n""\n""float3 RimLight(float3 rimColor, float3 N, float3 V, float power, float strength)\n""{\n""    float rim = pow(1.0 - saturate(dot(N, V)), max(power, 0.001));\n""    return rimColor * rim * strength;\n""}\n""\n""//--- 卡通阶梯 -------------------------------------------------------------\n""\n""// steps=3 时得到 0 / 0.5 / 1 三档明暗\n""float ToonRamp(float NdotL, float steps)\n""{\n""    float s = max(steps, 2.0);\n""    float band = floor(saturate(NdotL) * (s - 1.0) + 0.0001);\n""    return saturate(band / (s - 1.0));\n""}\n""\n""// 阶梯边界带一点过渡，feather 建议 0.01 ~ 0.3\n""float ToonRampSmooth(float NdotL, float steps, float feather)\n""{\n""    float s = max(steps, 2.0);\n""    float v = saturate(NdotL) * (s - 1.0);\n""    float band = floor(v);\n""    float f = smoothstep(1.0 - max(feather, 0.001), 1.0, frac(v));\n""    return saturate((band + f) / (s - 1.0));\n""}\n""\n""//============================================================================\n""// 管线场景脚手架（2D 伪 3D 光照，公式与内建着色器逐字一致）\n""//============================================================================\n""\n""//============================================================================\n""// N2a/N2b 平行光 shadow map 衰减（CSM 级联 + PCF）\n""//\n""// 2D 光空间扫掠体深度图（C 侧 stage_shadow_pass 把 castShadow 物体沿\n""// 背光方向拉伸成扫掠体渲染，深度恒 = 物体最朝光面 ndc.z ∈ [0,1]；\n""// D3D11 深度直通，GL/GLES 硬件深度 = ndc.z*0.5+0.5，采样后经 uShadowZx\n""// 还原回 ndc.z 值域比较）。\n""// N2b CSM：深度图集单张 1x4 横向分区（级 i 映 x∈[i/4,(i+1)/4]）；\n""// 级联选择按片元世界 v（= -world.x*lightDir.y + world.y*lightDir.x，\n""// uDirDir 为平行光方向）与 uShadowSplit 比较——级联数=1 时 split 全段\n""// （落 0 级 = N2a 语义零变化）。\n""// 采样：选级 lv → sp = mul(uLightVP_lv, world4)（sp.x = 柱 v、\n""// sp.y = 行 u、sp.z = 参考深度）；uv.x = 级内 ndc.x*0.125 + lv*0.25。\n""// P 被遮 ⟺ 深度图记录 < ref；ref = sp.z - bias（防 acne）。\n""// PCF：v 向 4 tap（±0.5/±1.5 纹素）。\n""//============================================================================\n""float ShadowAttenuation(float2 world)\n""{\n""    if (uShadowParam.x < 0.5 || uDirColor.a < 0.5) return 1.0;\n""    // 级联选择：片元世界 v 与分割表比较（级联数=1 时天然落 0 级）\n""    float vP = -world.x * uDirDir.y + world.y * uDirDir.x;\n""    int lv = 0;\n""    if (uShadowInfo.x > 2.5)\n""    {\n""        if (vP >= uShadowSplit.w) lv = 3;\n""        else if (vP >= uShadowSplit.z) lv = 2;\n""        else if (vP >= uShadowSplit.y) lv = 1;\n""    }\n""    // 级内光空间重投影（与渲染端 mul(uMVP, pos) 完全同构）\n""    float4 w4 = float4(world, 0.0, 1.0);\n""    float4 sp;\n""    if (lv == 0)      sp = mul(uLightVP,  w4);\n""    else if (lv == 1) sp = mul(uLightVP1, w4);\n""    else if (lv == 2) sp = mul(uLightVP2, w4);\n""    else              sp = mul(uLightVP3, w4);\n""    if (sp.x < -1.0 || sp.x > 1.0) return 1.0;   // 光视域外不遮\n""    if (sp.y < -1.0 || sp.y > 1.0) return 1.0;   // 行超视域不遮\n""    // 行 v 适配（zxform.zw）：GL/GLES RT 纹理 t=0 = 渲染 ndc.y=-1（恒等）；\n""    // D3D11 RT 纹理 v=0 = 渲染 ndc.y=+1（行序镜像）-> v = 1 - u_norm。\n""    // 图集 x：级内 ndc.x∈[-1,1] 映 [lv*0.25, (lv+1)*0.25]\n""    //（(ndc+1)*0.5 归一后乘分区宽 0.25 + 区基 lv*0.25）\n""    float2 uv = float2((sp.x * 0.5 + 0.5) * 0.25 + (float)lv * 0.25,\n""                      (sp.y * 0.5 + 0.5) * uShadowZx.z + uShadowZx.w);\n""    // N2A-DBG（临时可视化）：返回深度图 raw 采样值\n""    return uShadowTex.Sample(uShadowSamp, uv).r;\n""}\n""\n""// v3.3 基础光照（Lambert 无高光）：环境 + 直射 ndl + 聚光锥角/衰减。\n""// 与 FS_PFLAT/FS_PTEX 公式逐字一致（内建 v3.3 模型）。\n""// N2a：直射项挂 shadow map 衰减（ShadowAttenuation；关闭时恒 1，\n""// 输出与旧版逐字节一致——聚光/环境不参与 shadow map）。\n""float3 SceneBaseLight(float2 nrm2, float2 world)\n""{\n""    float3 light = uAmbient.xxx;\n""    if (uDirColor.a > 0.5)\n""        light += uDirColor.rgb * max(dot(nrm2, uDirDir.xy), 0.0)\n""                 * ShadowAttenuation(world);\n""    if (uSpotColor.a > 0.5)\n""    {\n""        float2 toF = world - uSpotPosRange.xy;\n""        float d = length(toF);\n""        float att = clamp(1.0 - d / max(uSpotPosRange.z, 1e-4), 0.0, 1.0);\n""        att *= att;\n""        float ca = dot(toF, uSpotDirCos.xy) / max(d, 1e-4);\n""        float ce = uSpotDirCos.z;\n""        light += uSpotColor.rgb * att * smoothstep(ce, ce + (1.0 - ce) * 0.5, ca);\n""    }\n""    return light;\n""}\n""\n""// 聚光衰减 × 锥角系数（v3.4 Phong 高光的聚光权重复用）\n""float SpotConeAtt(float2 world)\n""{\n""    float2 toF = world - uSpotPosRange.xy;\n""    float d = length(toF);\n""    float att = clamp(1.0 - d / max(uSpotPosRange.z, 1e-4), 0.0, 1.0);\n""    att *= att;\n""    float ca = dot(toF, uSpotDirCos.xy) / max(d, 1e-4);\n""    float ce = uSpotDirCos.z;\n""    return att * smoothstep(ce, ce + (1.0 - ce) * 0.5, ca);\n""}\n""\n""//============================================================================\n""// SlPhong.hlsl —— Phong（漫反射 + 镜面反射高光）\n""// 提炼自 RenderTest/shader/Phong.shader（Unity URP），零 Unity 依赖。\n""//\n""// Unity 原型：ShadePhong = DiffuseLambert + SpecularPhong\n""//   （_SpecColor 乘光色，step(0, NdotL) 门控高光），V = 相机 -> 像素。\n""// 2D 管线映射：V = (0,0,1)（伪 3D 家族约定）；漫反射沿用内建 v3.3 基座\n""//   （SceneBaseLight）；高光沿内建 FS_PHONG 公式 ——\n""//   N = normalize(float3(vNrm, 0.75))，直射 L = normalize(float3(uDirDir.xy, 0.6))，\n""//   聚光 L2 = normalize(float3(-toF / max(d, 1e-4), 0.6))，高光随锥角/距离衰减；\n""//   保留 Unity 的 NdotL > 0 高光门控；_SpecColor 取 Unity 默认白（省略）。\n""//\n""// uSpec[i.obj] 分量语义（xy 与内建 FS_PHONG_*.xy 一致）：\n""//   .x = 高光强度   .y = 光泽度（shininess）   .zw 未使用（保留）\n""//\n""// 变体契约 / 重新生成：同 SlLambert.hlsl 头注释。\n""//============================================================================\n""\n""struct SlVsIn\n""{\n""    float2 pos : POSITION;\n""    float2 uv  : TEXCOORD0;\n""};\n""\n""struct SlPsIn\n""{\n""    float4 pos   : SV_POSITION;\n""    float2 uv    : TEXCOORD0;\n""    float2 world : TEXCOORD1;\n""    float2 nrm   : TEXCOORD2;\n""    nointerpolation int obj : TEXCOORD3;   // 实例槽号（flat 传递给 frag）\n""};\n""\n""#ifndef SL_FLAT\n""Texture2D    uTex     : register(t0);\n""SamplerState uSampler : register(s0);\n""#endif\n""\n""// 场景顶点：与内建 VS_PSCENE 数学逐字一致（PerDraw 布局见共享核心）；\n""// 实例槽 = uObjIndex 基槽 + SV_InstanceID（单 draw 多实例连续排布）\n""SlPsIn vert(SlVsIn i, uint iid : SV_InstanceID)\n""{\n""    SlPsIn o;\n""    o.uv = i.uv;\n""    int obj = uObjIndex + (int)iid;\n""    int k = obj * 2;\n""    o.world = float2(dot(i.pos, uWMat[k].xy), dot(i.pos, uWMat[k].zw))\n""              + uWMat[k + 1].xy;\n""    o.nrm = uWMat[k + 1].zw;\n""    o.pos = mul(uMVP[obj], float4(i.pos, 0.0, 1.0));\n""    o.obj = obj;\n""    return o;\n""}\n""\n""// Phong：v3.3 漫反射基座 + 伪 3D 高光（R = reflect(-L, N)，NdotL>0 门控）\n""float4 frag(SlPsIn i) : SV_Target\n""{\n""#ifdef SL_FLAT\n""    float4 base = uColor[i.obj];\n""#else\n""    float4 base = uColor[i.obj] * uTex.Sample(uSampler, i.uv);\n""#endif\n""    float3 light = SceneBaseLight(i.nrm, i.world);\n""\n""    float3 N = normalize(float3(i.nrm, 0.75));\n""    float3 V = float3(0.0, 0.0, 1.0);\n""    float2 sp = uSpec[i.obj].xy;\n""    float shin = max(sp.y, 0.001);\n""\n""    if (uDirColor.a > 0.5)\n""    {\n""        float3 L = normalize(float3(uDirDir.xy, 0.6));\n""        float ndl = dot(N, L);\n""        // N2a：直射高光同样挂 shadow map 衰减（漫反射在 SceneBaseLight 内已挂）\n""        float shAtten = ShadowAttenuation(i.world);\n""        if (ndl > 0.0)   // Unity：step(0, NdotL) 门控高光\n""        {\n""            float3 R = reflect(-L, N);\n""            light += uDirColor.rgb * pow(max(dot(R, V), 0.0), shin) * sp.x * shAtten;\n""        }\n""    }\n""    if (uSpotColor.a > 0.5)\n""    {\n""        float cone = SpotConeAtt(i.world);\n""        float2 toF = i.world - uSpotPosRange.xy;\n""        float d = length(toF);\n""        float3 L2 = normalize(float3(-toF / max(d, 1e-4), 0.6));\n""        if (dot(N, L2) > 0.0)\n""        {\n""            float3 R2 = reflect(-L2, N);\n""            light += uSpotColor.rgb * cone\n""                      * pow(max(dot(R2, V), 0.0), shin) * sp.x;\n""        }\n""    }\n""    return float4(base.rgb * light, base.a);\n""}\n";
